public int CodePointBefore(int index)
{
    // Validate the index – the original Java code throws the result of
    // indexAndLength(index) when the index is out of range.
    if (index < 1 || index > count)
        throw indexAndLength(index);

    // In Java the call is: Character.codePointBefore(value, index);
    // In .NET we replicate the same behaviour using the UTF‑16 surrogate rules.
    // 'value' is assumed to be a char[] or a string that holds the underlying
    // characters (the same type used in the original class).

    // Get the code unit just before the supplied index.
    // (Java's `index` is 1‑based for this method, matching the check above.)
    int i = index - 1;               // zero‑based position of the preceding char
    char c = value[i];

    // If this char is a low‑surrogate and there is a preceding high‑surrogate,
    // combine them to obtain the full Unicode code point.
    if (char.IsLowSurrogate(c) && i > 0 && char.IsHighSurrogate(value[i - 1]))
    {
        // surrogate pair – compute the actual code point
        return char.ConvertToUtf32(value[i - 1], c);
    }

    // Not a surrogate pair – the code point is simply the UTF‑16 value.
    return c;
}
```

.public int CodePointBefore(int index)
{
