using System;
using System.IO;
using System.Text;

public void Save()
{
    // Prepare the byte array that will be written to disk
    byte[] outBytes;
    string text = ToText();

    if (utf8Bom)
    {
        // Write the UTF‑8 BOM (0xEF,0xBB,0xBF) followed by the UTF‑8 encoded text
        using (var ms = new MemoryStream())
        {
            ms.WriteByte(0xEF);
            ms.WriteByte(0xBB);
            ms.WriteByte(0xBF);
            byte[] txtBytes = Encoding.UTF8.GetBytes(text);
            ms.Write(txtBytes, 0, txtBytes.Length);
            outBytes = ms.ToArray();
        }
    }
    else
    {
        // Encode the text using the project's own encoding helper
        outBytes = Constants.Encode(text);
    }

    // Acquire an exclusive lock on the target file
    var lockFile = new LockFile(GetFile());
    if (!lockFile.Lock())
        throw new LockFailedException(GetFile());

    try
    {
        lockFile.NeedSnapshot = true;          // equivalent to setNeedSnapshot(true)
        lockFile.Write(outBytes);

        if (!lockFile.Commit())
            throw new IOException(
                string.Format(JGitText.Get().CannotCommitWriteTo, GetFile()));
    }
    finally
    {
        lockFile.Unlock();
    }

    // Update the snapshot and hash after a successful write
    snapshot = lockFile.CommitSnapshot;
    hash = Hash(outBytes);
    FireConfigChangedEvent();
}
```

**Notes on the translation**

* `ByteArrayOutputStream` → `MemoryStream`.
* `MessageFormat.format` → `string.Format`.
* Java’s `out` variable name is a keyword in C#, so it was renamed to `outBytes`.
* Property‑like calls (`setNeedSnapshot`, `setNeedSnapshot(true)`) were mapped to C# properties (`NeedSnapshot`), assuming `LockFile` exposes them that way.
* The method signatures (`ToText`, `GetFile`, `Constants.Encode`, `Hash`, `FireConfigChangedEvent`) are kept as‑is; they must exist in the surrounding C# class.

```csharp
public void Save()
{
    byte[] outBytes;
    string text = ToText();

    if (utf8Bom)
    {
        using (var ms = new MemoryStream())
        {
            ms.WriteByte(0xEF);
            ms.WriteByte(0xBB);
            ms.WriteByte(0xBF);
            byte[] txtBytes = Encoding.UTF8.GetBytes(text);
            ms.Write(txtBytes, 0, txtBytes.Length);
            outBytes = ms.ToArray();
        }
    }
    else
    {
        outBytes = Constants.Encode(text);
    }

    var lf = new LockFile(GetFile());
    if (!lf.Lock())
        throw new LockFailedException(GetFile());

    try
    {
        lf.SetNeedSnapshot(true);
        lf.Write(outBytes);
        if (!lf.Commit())
            throw new IOException(string.Format(JGitText.Get().CannotCommitWriteTo, GetFile()));
    }
    finally
    {
        lf.Unlock();
    }

    snapshot = lf.GetCommitSnapshot();
    hash = Hash(outBytes);
    FireConfigChangedEvent();
}
