using System;

public int CodePointBefore(int index)
{
    if (index < 1 || index > Count)
    {
        throw IndexAndLength(index);
    }

    // Get the code point that comes before the given index.
    // Handle surrogate pairs correctly.
    int i = index - 1;
    char c = Value[i];

    // If the current code unit is a low surrogate and the previous
    // code unit is a high surrogate, combine them to get the full
    // Unicode code point. Otherwise, the code point is just `c`.
    if (i > 0 && char.IsLowSurrogate(c) && char.IsHighSurrogate(Value[i - 1]))
    {
        return char.ConvertToUtf32(Value[i - 1], c);
    }

    return c;
}
