using System;
using System.IO;
using System.Text;

public void Save()
{
    byte[] outData;
    string text = ToText();

    if (utf8Bom)
    {
        using (var bos = new MemoryStream())
        {
            bos.WriteByte(0xEF);
            bos.WriteByte(0xBB);
            bos.WriteByte(0xBF);
            var textBytes = Encoding.UTF8.GetBytes(text);
            bos.Write(textBytes, 0, textBytes.Length);
            outData = bos.ToArray();
        }
    }
    else
    {
        outData = Constants.Encode(text);
    }

    var lf = new LockFile(GetFile());
    if (!lf.Lock())
    {
        throw new LockFailedException(GetFile());
    }

    try
    {
        lf.SetNeedSnapshot(true);
        lf.Write(outData);
        if (!lf.Commit())
        {
            throw new IOException(string.Format(JGitText.Get().CannotCommitWriteTo, GetFile()));
        }
    }
    finally
    {
        lf.Unlock();
    }

    snapshot = lf.GetCommitSnapshot();
    hash = Hash(outData);
    FireConfigChangedEvent();
}
```

public void Save()
{
    byte[] outBytes;
    string text = ToText();

    if (utf8Bom)
    {
        using (var bos = new MemoryStream())
        {
            bos.WriteByte(0xEF);
            bos.WriteByte(0xBB);
            bos.WriteByte(0xBF);
            bos.Write(Encoding.UTF8.GetBytes(text));
            outBytes = bos.ToArray();
        }
    }
    else
    {
        outBytes = Constants.Encode(text);
    }

    var lf = new LockFile(GetFile());
    if (!lf.Lock())
    {
        throw new LockFailedException(GetFile());
    }

    try
    {
        lf.SetNeedSnapshot(true);
        lf.Write(outBytes);
        if (!lf.Commit())
        {
            throw new IOException(string.Format(JGitText.Get().CannotCommitWriteTo, GetFile()));
        }
    }
    finally
    {
        lf.Unlock();
    }

    snapshot = lf.GetCommitSnapshot();
    hash = Hash(outBytes);
    FireConfigChangedEvent();
}

